import assert from "node:assert/strict";
import test from "node:test";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import path from "node:path";
import os from "node:os";
import { createInboxBatcher } from "../inbox-batcher.js";
import { createAnswerRelay, answerEnvelope, formatAnswerNote } from "../bearings-answer.js";
import { createThreadRelay, formatThreadNote, taggedEnvelope } from "../bearings-thread.js";
import { quarterdeckSendMatches } from "../authorship.js";
const uuid = (n) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const tick = () => new Promise((resolve) => setImmediate(resolve));
async function fixture(t, options = {}) {
  const directory = await mkdtemp(path.join(os.tmpdir(), "qd-outbox-"));
  const deliveries = [];
  const setup = { home: path.join(directory, "home"), statePath: path.join(directory, "state.json"), delayMs: 100,
    deliver: async (home, id, text) => { deliveries.push({ id, text }); return { id: "2000000000-note", request_id: id, saved: true, announced: true }; }, ...options };
  const batcher = createInboxBatcher(setup);
  t.after(async () => {
    batcher.close();
    await batcher.note.lookup("");
    await rm(directory, { recursive: true, force: true });
  });
  return { batcher, setup, deliveries };
}
const card = { key: "decision:example-task", type: "decision", task: "example-task", rev: "a".repeat(16), answer: { question: "example-task", options: [] } };
const model = { state: "ready", rev: "b".repeat(16), cards: [card] };
const answer = { requestId: uuid(1), key: card.key, cardRev: card.rev, selection: "", note: "Tuesday\nAfter checks" };
test("a burst preserves each envelope, uses one guarded request, and maps receipts to each item", async (t) => {
  const f = await fixture(t);
  const a = createAnswerRelay({ home: f.setup.home, note: f.batcher.note, receipts: f.batcher.receipts });
  const thread = createThreadRelay({ home: f.setup.home, note: f.batcher.note, receipts: f.batcher.receipts, transcript: async () => ({ turns: [] }) });
  const submissions = [a.submit(answer, model), thread.submit({ requestId: uuid(2), key: card.key, text: "What is next?" }, model)];
  const results = await Promise.all(submissions);
  assert.equal(f.deliveries.length, 1);
  assert.equal(results[0].noteId, results[1].noteId);
  const sent = f.deliveries[0];
  assert.ok(quarterdeckSendMatches(sent.id, sent.text));
  assert.ok(sent.text.includes(formatAnswerNote(answerEnvelope({ card, ...answer }, model.rev))));
  assert.ok(sent.text.includes(formatThreadNote({ card, key: card.key, text: "What is next?", requestId: uuid(2) })));
  const restored = createInboxBatcher({ ...f.setup, readReceipts: async () => ({ pending: [{ id: results[0].noteId, request_id: sent.id }], handled: [], replies: [] }) });
  t.after(() => restored.close());
  const history = await createThreadRelay({ home: f.setup.home, receipts: restored.receipts, transcript: async () => ({ turns: [] }) }).history(card.key, model);
  assert.equal(history.entries.filter((entry) => entry.from === "captain").length, 2);
  const retry = createAnswerRelay({ home: f.setup.home, note: restored.note });
  await retry.submit(answer, { cards: [] });
  assert.equal(f.deliveries.length, 1, "restart retry after card resolution does not deliver again");
  await assert.rejects(retry.submit({ ...answer, note: "Changed" }, model), /different answer/);
});
test("a lost delivery receipt retries exactly the sealed batch, including after restart", async (t) => {
  let fail = true;
  const seen = [];
  const f = await fixture(t, { deliver: async (home, id, text) => { seen.push({ id, text }); if (fail) throw Error("lost response"); return { id: "2000000000-note", request_id: id }; } });
  const promises = [f.batcher.note(f.setup.home, "quarterdeck-call:" + uuid(1), "First"), f.batcher.note(f.setup.home, "quarterdeck-thread:decision:example-task:" + uuid(2), "Second")];
  const settled = await Promise.allSettled(promises);
  assert.ok(settled.every((result) => result.status === "rejected"));
  f.batcher.close();
  fail = false;
  const restored = createInboxBatcher(f.setup);
  t.after(() => restored.close());
  await restored.flush();
  assert.deepEqual(seen[1], seen[0]);
});
test("page disappearance leaves saved work for restart; send now bypasses the window", async (t) => {
  const f = await fixture(t, { delayMs: 10000 });
  void f.batcher.note(f.setup.home, "quarterdeck-call:" + uuid(1), "Pending");
  await f.batcher.note.lookup("quarterdeck-call:" + uuid(1));
  f.batcher.close();
  const restarted = createInboxBatcher(f.setup);
  t.after(() => restarted.close());
  const before = Date.now();
  await restarted.note(f.setup.home, "quarterdeck-call:" + uuid(1), "Pending", { immediate: true });
  assert.ok(Date.now() - before < 1000);
  assert.equal(f.deliveries.length, 1);
});
test("batch provenance refuses mismatched identities and nested batches", async () => {
  const id = `quarterdeck-batch:${uuid(3)}`;
  const text = formatAnswerNote(answerEnvelope({ card, ...answer }, model.rev));
  const envelope = { schema: "fm-quarterdeck-inbox-batch.v1", requestId: id, items: [{ requestId: `quarterdeck-call:${uuid(1)}`, text }] };
  const format = () => `Batch\n\n\`\`\`json fm-quarterdeck-batch\n${JSON.stringify(envelope)}\n\`\`\``;
  assert.ok(quarterdeckSendMatches(id, format()));
  envelope.items[0].requestId = id;
  assert.equal(quarterdeckSendMatches(id, format()), false);
});
test("independent gateway instances preserve membership and a pending snapshot never clobbers a receipt", async (t) => {
  let complete, started;
  const inFlight = new Promise((resolve) => { started = resolve; });
  const f = await fixture(t, { delayMs: 10000, deliver: async (home, id) => {
    started(); await new Promise((resolve) => { complete = resolve; });
    return { id: "2000000000-note", request_id: id };
  } });
  const other = createInboxBatcher(f.setup);
  t.after(() => other.close());
  const one = f.batcher.note(f.setup.home, "quarterdeck-call:" + uuid(1), "One");
  await f.batcher.note.lookup("quarterdeck-call:" + uuid(1));
  const two = other.note(f.setup.home, "quarterdeck-call:" + uuid(2), "Two");
  await other.note.lookup("quarterdeck-call:" + uuid(2));
  assert.equal((await f.batcher.pending()).length, 2);
  const flushing = f.batcher.flush();
  await inFlight;
  assert.equal((await f.batcher.pending()).length, 2, "lock-free status is safe during delivery");
  complete();
  await flushing;
  await one;
  await other.flush();
  await two;
  assert.deepEqual(await f.batcher.pending(), []);
});
test("failure of an earlier sealed batch releases later callers and keeps all pending items", async (t) => {
  let fail = true;
  const f = await fixture(t, { delayMs: 10000, deliver: async () => { if (fail) throw Error("offline"); return { id: "2000000000-note" }; } });
  const first = f.batcher.note(f.setup.home, "quarterdeck-call:" + uuid(1), "First");
  const firstFailure = assert.rejects(first, /offline/);
  await f.batcher.note.lookup("quarterdeck-call:" + uuid(1));
  await assert.rejects(f.batcher.flush(), /offline/);
  await firstFailure;
  const second = f.batcher.note(f.setup.home, "quarterdeck-call:" + uuid(2), "Second");
  const secondFailure = assert.rejects(second, /offline/);
  await f.batcher.note.lookup("quarterdeck-call:" + uuid(2));
  await assert.rejects(f.batcher.flush(), /offline/);
  await secondFailure;
  assert.equal((await f.batcher.pending()).length, 2);
  fail = false;
  await f.batcher.flush();
  assert.deepEqual(await f.batcher.pending(), []);
});

for (const urgentNote of [false, true]) test(`${urgentNote ? "urgent-note" : "direct"} retries bound stalled arrivals after a failed delivery`, { timeout: 5000 }, async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout", "Date"], now: 2000000000000 });
  let fail = true;
  const attempts = [];
  const f = await fixture(t, { delayMs: 3000, deliver: async (home, id, text) => {
    attempts.push({ id, text });
    if (fail) throw Error("offline");
    return { id: "2000000000-note", request_id: id };
  } });
  const id = "quarterdeck-call:" + uuid(1);
  const first = f.batcher.note(f.setup.home, id, "Retained answer");
  const failure = assert.rejects(first, /offline/);
  await f.batcher.note.lookup(id);
  await assert.rejects(f.batcher.flush(), /offline/);
  await failure;
  const arrived = f.batcher.arrive();
  t.after(arrived);
  fail = false;
  const retry = urgentNote ? f.batcher.note(f.setup.home, id, "Retained answer", { immediate: true }) : f.batcher.flush();
  if (urgentNote) await f.batcher.note.lookup(id);
  t.mock.timers.tick(2999);
  await tick();
  assert.equal(attempts.length, 1, "a stalled sibling retains the batching window");
  t.mock.timers.tick(1);
  await retry;
  assert.equal(attempts.length, 2, "the debounce deadline releases delivery without the sibling finishing");
  assert.deepEqual(attempts[1], attempts[0], "retry preserves the sealed submission");
  assert.deepEqual(await f.batcher.pending(), []);
});

test("saving an answer supersedes an earlier direct flush fallback until its sibling saves", { timeout: 5000 }, async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout", "Date"], now: 2000000000000 });
  const f = await fixture(t, { delayMs: 3000 });
  const answerArrived = f.batcher.arrive(), threadArrived = f.batcher.arrive();
  t.after(answerArrived);
  t.after(threadArrived);
  const flushing = f.batcher.flush();
  t.mock.timers.tick(1000);
  const answerId = "quarterdeck-call:" + uuid(1), threadId = "quarterdeck-thread:" + card.key + ":" + uuid(2);
  const answered = f.batcher.note(f.setup.home, answerId, "Tuesday", { immediate: true, arrived: answerArrived });
  await f.batcher.note.lookup(answerId);
  t.mock.timers.tick(2000);
  await tick();
  await f.batcher.note.lookup(answerId);
  assert.equal(f.deliveries.length, 0, "the direct flush must respect the saved answer's later debounce deadline");
  t.mock.timers.tick(500);
  const asked = f.batcher.note(f.setup.home, threadId, "Which window?", { immediate: true, arrived: threadArrived });
  const [answerReceipt, threadReceipt] = await Promise.all([answered, asked, flushing]);
  assert.equal(f.deliveries.length, 1, "siblings saved within the debounce window produce one inbox wake");
  assert.equal(answerReceipt.id, threadReceipt.id);
  assert.deepEqual(taggedEnvelope(f.deliveries[0].text, "fm-quarterdeck-batch").items.map((item) => item.requestId), [answerId, threadId]);
});

test("urgent waits follow a debounce deadline extended by subsequent saves", { timeout: 5000 }, async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout", "Date"], now: 2000000000000 });
  const f = await fixture(t, { delayMs: 3000 });
  const arrivals = [f.batcher.arrive(), f.batcher.arrive(), f.batcher.arrive()];
  for (const arrived of arrivals) t.after(arrived);
  const ids = [1, 2, 3].map((n) => "quarterdeck-call:" + uuid(n));
  const first = f.batcher.note(f.setup.home, ids[0], "First", { immediate: true, arrived: arrivals[0] });
  await f.batcher.note.lookup(ids[0]);
  const flushing = f.batcher.flush();
  t.mock.timers.tick(2000);
  const second = f.batcher.note(f.setup.home, ids[1], "Second", { immediate: true, arrived: arrivals[1] });
  await f.batcher.note.lookup(ids[1]);
  t.mock.timers.tick(1000);
  await tick();
  await f.batcher.note.lookup(ids[1]);
  assert.equal(f.deliveries.length, 0, "the original urgent wait must respect the extended debounce deadline");
  t.mock.timers.tick(1000);
  const third = f.batcher.note(f.setup.home, ids[2], "Third", { immediate: true, arrived: arrivals[2] });
  const receipts = await Promise.all([first, second, third, flushing]);
  assert.equal(f.deliveries.length, 1, "all three items saved within five seconds share one inbox wake");
  assert.ok(receipts.slice(0, 3).every((receipt) => receipt.id === receipts[0].id));
  assert.deepEqual(taggedEnvelope(f.deliveries[0].text, "fm-quarterdeck-batch").items.map((item) => item.requestId), ids);
});

test("a sibling arriving after the initial flush check joins the unsealed answer", { timeout: 5000 }, async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout", "Date"], now: 2000000000000 });
  const f = await fixture(t, { delayMs: 3000 });
  const answerId = "quarterdeck-call:" + uuid(1), threadId = "quarterdeck-thread:" + card.key + ":" + uuid(2);
  const answered = f.batcher.note(f.setup.home, answerId, "Tuesday");
  await f.batcher.note.lookup(answerId);
  const flushing = f.batcher.flush();
  await Promise.resolve();
  const arrived = f.batcher.arrive();
  t.after(arrived);
  const asked = f.batcher.note(f.setup.home, threadId, "Which window?", { immediate: true, arrived });
  const [answerReceipt, threadReceipt] = await Promise.all([answered, asked, flushing]);
  assert.equal(f.deliveries.length, 1, "a sibling received before sealing shares the queued Send's inbox wake");
  assert.equal(answerReceipt.id, threadReceipt.id);
  assert.deepEqual(taggedEnvelope(f.deliveries[0].text, "fm-quarterdeck-batch").items.map((item) => item.requestId), [answerId, threadId]);
});

test('persisted same-ID answers and thread notes replay their original cycle without a new cycle field', async t => {
  const f = await fixture(t);
  const firstCard = { ...card, holdVersion: '1'.repeat(16) }, secondCard = { ...card, holdVersion: '2'.repeat(16) };
  const originalModel = { ...model, cards: [firstCard] }, reheld = { ...model, cards: [secondCard] };
  const answerBody = { ...answer, holdVersion: firstCard.holdVersion };
  const threadBody = { requestId: uuid(2), key: card.key, text: 'Question about cycle A', holdVersion: firstCard.holdVersion };
  const answers = createAnswerRelay({ home: f.setup.home, note: f.batcher.note });
  const threads = createThreadRelay({ home: f.setup.home, note: f.batcher.note });
  const original = await Promise.all([answers.submit(answerBody, originalModel), threads.submit(threadBody, originalModel)]);
  assert.equal(f.deliveries.length, 1);
  const sealed = f.deliveries[0].text;
  f.batcher.close();
  const restored = createInboxBatcher(f.setup);
  t.after(() => restored.close());
  const restartedAnswers = createAnswerRelay({ home: f.setup.home, note: restored.note });
  const restartedThreads = createThreadRelay({ home: f.setup.home, note: restored.note });
  const answerRetry = await restartedAnswers.submit(answer, reheld);
  const threadRetry = await restartedThreads.submit({ requestId: uuid(2), key: card.key, text: threadBody.text }, reheld);
  assert.equal(answerRetry.envelope.holdVersion, firstCard.holdVersion);
  assert.equal(threadRetry.holdVersion, firstCard.holdVersion);
  assert.equal(answerRetry.noteId, original[0].noteId);
  assert.equal(threadRetry.noteId, original[1].noteId);
  assert.equal(f.deliveries.length, 1);
  assert.equal(f.deliveries[0].text, sealed);
});
